//! The table port against @tanstack/table-core 9.3.1 itself, over the
//! seeded tables and operations in tests/fixtures/table-oracle.json
//! (generated by tools/table-oracle/generate.mjs). Each case replays its
//! steps on the port, and every snapshot must equal the package's exactly:
//! the same row order, state, header groups and f64 sizes.

use std::rc::Rc;

use sample_interactions::table::{
    value::to_js_string, Accessor, BuiltinSortFn, ColumnDef, ColumnResizeDirection,
    ColumnResizeMode, ColumnSort, CustomSortFn, HeaderGroups, ObjectMap, ResizeSession,
    ResizeStart, SortFnSpec, SortUndefined, Table, TableOptions, Value,
};
use serde_json::{json, Value as Json};

const FIXTURE: &str = include_str!("fixtures/table-oracle.json");

// ------------------------------------------------------------ decoding

/// A tagged fixture value as JavaScript held it.
fn decode(json: &Json) -> Value {
    match json {
        Json::Null => Value::Null,
        Json::Bool(b) => Value::Bool(*b),
        Json::Number(n) => Value::Number(n.as_f64().unwrap()),
        Json::String(s) => Value::String(s.clone()),
        Json::Array(items) => Value::Array(items.iter().map(decode).collect()),
        Json::Object(map) => {
            if let Some(tag) = map.get("$") {
                match tag.as_str().unwrap() {
                    "undefined" => Value::Undefined,
                    "NaN" => Value::Number(f64::NAN),
                    "Infinity" => Value::Number(f64::INFINITY),
                    "-Infinity" => Value::Number(f64::NEG_INFINITY),
                    "-0" => Value::Number(-0.0),
                    other => panic!("unknown tag {other}"),
                }
            } else if let Some(time) = map.get("$date") {
                let Value::Number(time) = decode(time) else {
                    panic!("date time")
                };
                Value::Date(time)
            } else {
                Value::Object(map.iter().map(|(k, v)| (k.clone(), decode(v))).collect())
            }
        }
    }
}

fn number(json: &Json) -> f64 {
    match decode(json) {
        Value::Number(n) => n,
        other => panic!("expected a number, found {other:?}"),
    }
}

/// table-core's vanilla sorting example's custom sort function.
fn status_order() -> CustomSortFn {
    const ORDER: [&str; 3] = ["single", "complicated", "relationship"];
    let index = |value: Value| match value {
        Value::String(s) => ORDER
            .iter()
            .position(|o| *o == s)
            .map_or(-1.0, |i| i as f64),
        _ => -1.0,
    };
    CustomSortFn {
        name: "statusOrder".into(),
        compare: Rc::new(move |table: &Table, a, b, id: &str| {
            index(table.value(a, id)) - index(table.value(b, id))
        }),
    }
}

fn column_def(spec: &Json) -> ColumnDef {
    let mut def = ColumnDef::default();
    for (key, value) in spec.as_object().unwrap() {
        match key.as_str() {
            "id" => def.id = Some(value.as_str().unwrap().into()),
            "accessorKey" => def.accessor = Some(Accessor::Key(value.as_str().unwrap().into())),
            "accessorFn" => {
                let key = value.as_str().unwrap().to_owned();
                def.accessor = Some(Accessor::Fn(Rc::new(move |row: &Value, _| row.get(&key))));
            }
            "header" => def.header = Some(value.as_str().unwrap().into()),
            "columns" => def.columns = value.as_array().unwrap().iter().map(column_def).collect(),
            "size" => def.size = Some(number(value)),
            "minSize" => def.min_size = Some(number(value)),
            "maxSize" => def.max_size = Some(number(value)),
            "enableSorting" => def.enable_sorting = value.as_bool(),
            "invertSorting" => def.invert_sorting = value.as_bool(),
            "sortDescFirst" => def.sort_desc_first = value.as_bool(),
            "enableMultiSort" => def.enable_multi_sort = value.as_bool(),
            "enableResizing" => def.enable_resizing = value.as_bool(),
            "sortFn" => {
                def.sort_fn = Some(match value.as_str().unwrap() {
                    "auto" => SortFnSpec::Auto,
                    "custom:statusOrder" => SortFnSpec::Custom(status_order()),
                    name => SortFnSpec::Named(name.into()),
                })
            }
            "sortUndefined" => {
                def.sort_undefined = Some(match value {
                    Json::Bool(false) => SortUndefined::Disabled,
                    Json::String(s) if s == "first" => SortUndefined::First,
                    Json::String(s) if s == "last" => SortUndefined::Last,
                    other => SortUndefined::Number(number(other)),
                })
            }
            other => panic!("unknown column field {other}"),
        }
    }
    def
}

fn sorting(json: &Json) -> Vec<ColumnSort> {
    json.as_array()
        .unwrap()
        .iter()
        .map(|entry| ColumnSort {
            id: entry[0].as_str().unwrap().into(),
            desc: entry[1].as_bool().unwrap(),
        })
        .collect()
}

fn sizing(json: &Json) -> ObjectMap<f64> {
    ObjectMap::from_entries(
        json.as_array()
            .unwrap()
            .iter()
            .map(|entry| (entry[0].as_str().unwrap().to_owned(), number(&entry[1]))),
    )
}

fn build(spec: &Json) -> Table {
    let mut options = TableOptions::default();
    if let Some(map) = spec.get("options").and_then(Json::as_object) {
        for (key, value) in map {
            match key.as_str() {
                "enableSorting" => options.enable_sorting = value.as_bool(),
                "enableMultiSort" => options.enable_multi_sort = value.as_bool(),
                "enableSortingRemoval" => options.enable_sorting_removal = value.as_bool(),
                "enableMultiRemove" => options.enable_multi_remove = value.as_bool(),
                "maxMultiSortColCount" => options.max_multi_sort_col_count = Some(number(value)),
                "sortDescFirst" => options.sort_desc_first = value.as_bool(),
                "enableColumnResizing" => options.enable_column_resizing = value.as_bool(),
                "columnResizeMode" => {
                    assert_eq!(value, "onChange");
                    options.column_resize_mode = ColumnResizeMode::OnChange;
                }
                "columnResizeDirection" => {
                    assert_eq!(value, "rtl");
                    options.column_resize_direction = ColumnResizeDirection::Rtl;
                }
                "defaultColumn" => options.default_column = column_def(value),
                "getRowId" => {
                    let key = value.as_str().unwrap().to_owned();
                    options.get_row_id =
                        Some(Rc::new(move |row: &Value, _, _| match row.get(&key) {
                            Value::Undefined | Value::Null => None,
                            Value::String(s) => Some(s),
                            other => Some(to_js_string(&other)),
                        }));
                }
                "getSubRows" => {
                    let key = value.as_str().unwrap().to_owned();
                    options.get_sub_rows =
                        Some(Rc::new(move |row: &Value, _| match row.get(&key) {
                            Value::Array(items) => Some(items),
                            _ => None,
                        }));
                }
                other => panic!("unknown option {other}"),
            }
        }
    }
    if let Some(names) = spec.get("sortFns") {
        options.sort_fns = Some(
            names
                .as_array()
                .unwrap()
                .iter()
                .map(|name| BuiltinSortFn::from_name(name.as_str().unwrap()).unwrap())
                .collect(),
        );
    }
    if let Some(initial) = spec.get("initialState") {
        options.initial_sorting = initial.get("sorting").map(sorting);
        options.initial_column_sizing = initial.get("columnSizing").map(sizing);
    }
    let columns: Vec<ColumnDef> = spec["columns"]
        .as_array()
        .unwrap()
        .iter()
        .map(column_def)
        .collect();
    let Value::Array(data) = decode(&spec["data"]) else {
        panic!("data")
    };
    Table::new(&columns, &data, options)
}

// ----------------------------------------------------------- snapshots

fn encode(n: f64) -> Json {
    if n.is_nan() {
        json!({"$": "NaN"})
    } else if n == f64::INFINITY {
        json!({"$": "Infinity"})
    } else if n == f64::NEG_INFINITY {
        json!({"$": "-Infinity"})
    } else if n == 0.0 && n.is_sign_negative() {
        json!({"$": "-0"})
    } else {
        json!(n)
    }
}

fn optional(n: Option<f64>) -> Json {
    n.map_or(Json::Null, encode)
}

fn direction(d: Option<sample_interactions::table::SortDirection>) -> Json {
    d.map_or(json!(false), |d| json!(d.name()))
}

fn snapshot(table: &Table) -> Json {
    let model = table.sorted_row_model();
    let groups: HeaderGroups = table.header_groups();
    let row_id = |row: usize| json!(table.rows[row].id);
    let columns: Vec<Json> = table
        .all_flat_columns()
        .into_iter()
        .map(|c| {
            json!([
                table.columns[c].id,
                table.columns[c].depth,
                table.can_sort(c),
                table.can_multi_sort(c),
                direction(table.is_sorted(c)),
                table.sort_index(c),
                direction(table.next_sorting_order(c, false)),
                table.first_sort_dir(c).name(),
                table.auto_sort_dir(c).name(),
                table.sort_fn(c).name(),
                encode(table.column_size(c)),
                encode(table.column_start(c)),
                encode(table.column_after(c)),
                table.can_resize(c),
                table.is_resizing(c),
            ])
        })
        .collect();
    let header_groups: Vec<Json> = groups
        .groups
        .iter()
        .map(|group| {
            let headers: Vec<Json> = group
                .headers
                .iter()
                .map(|&h| {
                    let header = &groups.headers[h];
                    let ids = |list: &[usize]| {
                        list.iter()
                            .map(|&s| json!(groups.headers[s].id))
                            .collect::<Vec<_>>()
                    };
                    json!([
                        header.id,
                        table.columns[header.column].id,
                        header.index,
                        header.depth,
                        header.col_span,
                        header.row_span,
                        header.is_placeholder,
                        header.placeholder_id,
                        encode(table.header_size(&groups, h)),
                        encode(table.header_start(&groups, h)),
                        ids(&header.sub_headers),
                        ids(&groups.leaf_headers(h)),
                    ])
                })
                .collect();
            json!([group.id, group.depth, headers])
        })
        .collect();
    let resizing = &table.state.column_resizing;
    json!({
        "sorting": table.state.sorting.iter().map(|s| json!([s.id, s.desc])).collect::<Vec<_>>(),
        "rows": model.rows.iter().map(|r| row_id(r.row)).collect::<Vec<_>>(),
        "flat": model.flat_rows.iter().map(|&r| row_id(r)).collect::<Vec<_>>(),
        "columns": columns,
        "headerGroups": header_groups,
        "totalSize": encode(table.total_size(&groups)),
        "columnSizing": table.state.column_sizing.entries().into_iter().map(|(k, v)| json!([k, encode(v)])).collect::<Vec<_>>(),
        "columnResizing": {
            "startOffset": optional(resizing.start_offset),
            "startSize": optional(resizing.start_size),
            "deltaOffset": optional(resizing.delta_offset),
            "deltaPercentage": optional(resizing.delta_percentage),
            "isResizingColumn": resizing.is_resizing_column.as_ref().map_or(json!(false), |id| json!(id)),
            "columnSizingStart": resizing.column_sizing_start.iter().map(|(id, size)| json!([id, encode(*size)])).collect::<Vec<_>>(),
        },
    })
}

/// Equal, with numbers compared bitwise (both sides tag -0 and the
/// non-finite values).
fn same(a: &Json, b: &Json) -> bool {
    match (a, b) {
        (Json::Number(a), Json::Number(b)) => {
            a.as_f64().unwrap().to_bits() == b.as_f64().unwrap().to_bits()
        }
        (Json::Array(a), Json::Array(b)) => {
            a.len() == b.len() && a.iter().zip(b).all(|(a, b)| same(a, b))
        }
        (Json::Object(a), Json::Object(b)) => {
            a.len() == b.len() && a.iter().all(|(k, v)| b.get(k).is_some_and(|w| same(v, w)))
        }
        _ => a == b,
    }
}

// --------------------------------------------------------------- steps

fn apply(table: &mut Table, session: &mut Option<ResizeSession>, step: &Json) {
    let column = |table: &Table| {
        let id = step["column"].as_str().unwrap();
        table.column(id).unwrap_or_else(|| panic!("no column {id}"))
    };
    match step["op"].as_str().unwrap() {
        "toggle" => {
            let c = column(table);
            table.toggle_sorting(
                c,
                step.get("desc").and_then(Json::as_bool),
                step.get("multi").and_then(Json::as_bool),
            );
        }
        "click" => {
            let c = column(table);
            let event = sample_interactions::table::SortEvent {
                shift_key: step["shift"].as_bool().unwrap(),
            };
            table.toggle_sorting_handler(c, &event);
        }
        "clear" => {
            let c = column(table);
            table.clear_sorting(c);
        }
        "setSorting" => table.set_sorting(sorting(&step["sorting"])),
        "resetSorting" => table.reset_sorting(step["defaultState"].as_bool().unwrap()),
        "resizeStart" => {
            let groups = table.header_groups();
            let header = groups
                .find(step["header"].as_str().unwrap())
                .expect("header");
            let event = match step.get("touches") {
                Some(touches) => ResizeStart::Touch {
                    touches: touches.as_array().unwrap().iter().map(number).collect(),
                },
                None => ResizeStart::Mouse {
                    client_x: number(&step["x"]),
                },
            };
            if let Some(started) = table.begin_resize(&groups, header, event) {
                assert!(session.is_none(), "the oracle never overlaps drags");
                *session = Some(started);
            }
        }
        "move" => {
            let touch = step.get("touch").is_some();
            if let Some(active) = session.as_mut().filter(|s| s.touch == touch) {
                // Node has no requestAnimationFrame: each move applies.
                active.on_move(table, number(&step["x"]), false);
            }
        }
        "end" => {
            let touch = step.get("touch").is_some() || step.get("cancel").is_some();
            if session.as_ref().is_some_and(|s| s.touch == touch) {
                let x = if step.get("cancel").is_some() {
                    None
                } else {
                    step.get("x").map(number)
                };
                session.take().unwrap().on_end(table, x);
            }
        }
        "setColumnSizing" => table.set_column_sizing(sizing(&step["sizing"])),
        "resetSize" => {
            let c = column(table);
            table.reset_size(c);
        }
        "resetColumnSizing" => table.reset_column_sizing(step["defaultState"].as_bool().unwrap()),
        other => panic!("unknown op {other}"),
    }
}

const FIELDS: [&str; 9] = [
    "sorting",
    "rows",
    "flat",
    "columns",
    "headerGroups",
    "totalSize",
    "columnSizing",
    "columnResizing",
    "all",
];

#[test]
fn table_core_snapshots_match_the_package() {
    let fixture: Json = serde_json::from_str(FIXTURE).unwrap();
    let mut equal = [0usize; FIELDS.len()];
    let mut total = 0;
    let mut failures = Vec::new();
    for spec in fixture["cases"].as_array().unwrap() {
        let name = spec
            .get("name")
            .and_then(Json::as_str)
            .map_or_else(|| format!("seed {}", spec["seed"]), str::to_owned);
        let mut table = build(spec);
        let mut session = None;
        let expected = spec["snapshots"].as_array().unwrap();
        let steps = spec["steps"].as_array().unwrap();
        for (n, theirs) in expected.iter().enumerate() {
            if n > 0 {
                apply(&mut table, &mut session, &steps[n - 1]);
            }
            let ours = snapshot(&table);
            total += 1;
            let mut all = true;
            for (i, field) in FIELDS[..FIELDS.len() - 1].iter().enumerate() {
                if same(&ours[field], &theirs[field]) {
                    equal[i] += 1;
                } else {
                    all = false;
                    if failures.len() < 12 {
                        let clip = |v: &Json| v.to_string().chars().take(400).collect::<String>();
                        failures.push(format!(
                            "{name} #{n} {field}: port {}, package {}",
                            clip(&ours[field]),
                            clip(&theirs[field])
                        ));
                    }
                }
            }
            if all {
                equal[FIELDS.len() - 1] += 1;
            }
        }
    }
    for (i, field) in FIELDS.iter().enumerate() {
        println!("ORACLE table {field}: {}/{total}", equal[i]);
    }
    println!("({})", fixture["packages"].as_str().unwrap());
    assert!(failures.is_empty(), "differences:\n{}", failures.join("\n"));
}
